CREATE TABLE public.mapper_delivery_queue (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), formulario_id bigint NOT NULL, action text NOT NULL, payload jsonb NOT NULL, delivered_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.mapper_delivery_queue TO service_role;
ALTER TABLE public.mapper_delivery_queue ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.mapper_enqueue_delivery() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' OR (NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN ('approved','rejected')) THEN INSERT INTO public.mapper_delivery_queue(formulario_id,action,payload) VALUES(NEW.id,CASE WHEN TG_OP='INSERT' THEN 'new' ELSE NEW.status END,to_jsonb(NEW)); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.mapper_enqueue_delivery() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER mapper_delivery_after_write AFTER INSERT OR UPDATE OF status ON public.formularios FOR EACH ROW EXECUTE FUNCTION public.mapper_enqueue_delivery();
CREATE OR REPLACE FUNCTION public.mapper_submit_with_receipt(_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE fid bigint; token uuid; BEGIN fid:=public.mapper_submit_form(_data); SELECT id INTO token FROM public.mapper_delivery_queue WHERE formulario_id=fid AND action='new' ORDER BY created_at DESC LIMIT 1; RETURN jsonb_build_object('id',fid,'receipt',token); END $$;
REVOKE ALL ON FUNCTION public.mapper_submit_with_receipt(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.mapper_submit_with_receipt(jsonb) TO anon,authenticated,service_role;
REVOKE EXECUTE ON FUNCTION public.mapper_submit_form(jsonb) FROM anon,authenticated;
COMMENT ON FUNCTION public.mapper_submit_form(jsonb) IS 'Internal validated submission helper, called only through the receipt wrapper; not exposed to anonymous or authenticated callers.';
COMMENT ON FUNCTION public.mapper_submit_with_receipt(jsonb) IS 'Intentional public submission endpoint. Validates server, mandatory identity fields, per-server lock and atomic 48-hour duplicate/release rules. Does not read private records; returns only new ID and unguessable delivery receipt.';
COMMENT ON FUNCTION public.mapper_access_server(text) IS 'Intentional authenticated permission predicate: requires auth.uid and evaluates server membership from protected role records.';
COMMENT ON FUNCTION public.mapper_current_identity() IS 'Intentional authenticated identity endpoint: only current JWT email role, server and nick.';
COMMENT ON FUNCTION public.mapper_list_members() IS 'Intentional authenticated scoped member list: mapper membership required; email omitted for non-general roles.';
COMMENT ON FUNCTION public.mapper_save_member(uuid,text,text,text,text,text) IS 'Intentional authenticated member operation: validates old and new hierarchy/server permissions, protects founder and self, requires nick/RG and normalized email.';
COMMENT ON FUNCTION public.mapper_remove_member(uuid) IS 'Intentional authenticated member operation: validates target role and server, rejects founder and self.';
COMMENT ON FUNCTION public.mapper_list_forms(bigint) IS 'Intentional authenticated read boundary: filters each form by actor server permission and removes email for non-general roles.';
COMMENT ON FUNCTION public.mapper_form_history(bigint) IS 'Intentional authenticated history read boundary: requires access to parent form server, removes actor email for non-general roles.';
COMMENT ON FUNCTION public.mapper_decide_form(bigint,text,text,boolean) IS 'Intentional authenticated atomic decision boundary: locks form, checks server scope, status transition, reason and revision role, writes audit in same transaction.';
COMMENT ON FUNCTION public.mapper_edit_form(bigint,jsonb) IS 'Intentional authenticated edit boundary: requires responsible/general role and both old/new server access; prevents status/id/audit field changes.';
COMMENT ON FUNCTION public.mapper_delete_form(bigint) IS 'Intentional authenticated delete boundary: requires signed-in general role.';
COMMENT ON FUNCTION public.mapper_create_release(text,text,text,text) IS 'Intentional authenticated release boundary: requires responsible/general role and server scope.';